.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: var(--header-bg);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 24px;
  height: 64px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  font-weight: 700;
  letter-spacing: -0.02em;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--accent);
  color: var(--accent-ink);
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-weight: 800;
  font-size: 1rem;
  box-shadow: 0 0 18px var(--glow);
}

.brand-name {
  font-size: 1.1rem;
}

.nav {
  display: flex;
  gap: 26px;
  margin-left: auto;
}

.nav a {
  color: var(--text-muted);
  font-size: 0.92rem;
  font-weight: 500;
  transition: color 0.2s ease;
}

.nav a:hover {
  color: var(--text);
}

.theme-toggle {
  appearance: none;
  border: 1px solid var(--border-strong);
  background: var(--card);
  color: var(--text);
  width: 38px;
  height: 38px;
  border-radius: 10px;
  cursor: pointer;
  display: grid;
  place-items: center;
  font-size: 1rem;
  transition: border-color 0.2s ease, transform 0.15s ease;
}

.theme-toggle:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}

.theme-toggle .icon-sun {
  display: none;
}

[data-theme="light"] .theme-toggle .icon-sun {
  display: inline;
}

[data-theme="light"] .theme-toggle .icon-moon {
  display: none;
}

/* ============ Hero ============ */
.hero {
  position: relative;
  padding: 108px 0 96px;
  overflow: hidden;
}

.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(640px 360px at 18% -10%, var(--glow), transparent 70%),
    radial-gradient(520px 300px at 90% 20%, rgba(80, 140, 255, 0.08), transparent 70%);
  pointer-events: none;
}

.hero-grid {
  position: relative;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 56px;
  align-items: center;
}

.hero-copy h1 {
  font-size: clamp(3rem, 7vw, 4.8rem);
  font-weight: 800;
  margin-bottom: 18px;
}

.accent-dot {
  color: var(--accent);
}

.tagline {
  font-size: clamp(1.05rem, 2vw, 1.25rem);
  max-width: 34ch;
  margin-bottom: 28px;
}

.hero-badges {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 36px;
}

.hero-badges li {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid var(--accent-soft);
  padding: 6px 14px;
  border-radius: 999px;
  letter-spacing: 0.01em;
}

.hero-actions {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}

.btn {
  display: inline-block;
  padding: 12px 22px;
  border-radius: 12px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid transparent;
  transition: transform 0.15s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
  box-shadow: 0 8px 24px var(--glow);
}

.btn-primary:hover {
  box-shadow: 0 12px 32px var(--glow);
}

.btn-ghost {
  border-color: var(--border-strong);
  color: var(--text);
  background: transparent;
}

.btn-ghost:hover {
  border-color: var(--accent);
  background: var(--accent-soft);
}

/* ============ Event demo ============ */
.event-demo {
  border: 1px solid var(--border-strong);
  border-radius: 16px;
  background: var(--card);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

[data-theme="light"] .event-demo {
  box-shadow: 0 20px 48px rgba(24, 32, 46, 0.12);
}

.demo-bar {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-soft);
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.dot-red { background: #ff5f57; }
.dot-amber { background: #febc2e; }
.dot-green { background: #28c840; }

.demo-title {
  margin-left: 8px;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.78rem;
  color: var(--text-faint);
}

.demo-body {
  padding: 18px 16px 16px;
  min-height: 188px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.demo-log {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.8rem;
}

.log-line {
  color: var(--text-faint);
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.log-line::before {
  content: "→";
  color: var(--accent);
}

.log-line.is-current {
  color: var(--text);
}

.demo-current {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--code-bg);
  margin-top: auto;
}

.demo-event-name {
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 0.02em;
}

.demo-spinner {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid var(--border-strong);
  border-top-color: var(--accent);
  animation: spin 0.9s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.demo-caption {
  font-size: 0.78rem;
  text-align: center;
  padding: 0 16px 14px;
  color: var(--text-faint);
}

/* ============ Steps ============ */
.steps {
  list-style: none;
  display: grid;
  gap: 18px;
  counter-reset: step;
}

.step {
  display: flex;
  gap: 20px;
  padding: 22px 24px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--card);
  transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
}

.step:hover {
  border-color: var(--border-strong);
  transform: translateX(4px);
  background: var(--card-hover);
}

.step-num {
  flex: 0 0 auto;
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: var(--accent-soft);
  color: var(--accent);
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-weight: 800;
  font-size: 1.05rem;
  border: 1px solid var(--accent-soft);
}

.step-body h3 {
  font-size: 1.08rem;
  margin-bottom: 4px;
}

.step-body p {
  font-size: 0.95rem;
}

/* ============ Cards ============ */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 18px;
}

.card {
  padding: 26px 24px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--card);
  transition: border-color 0.2s ease, transform 0.2s ease, background 0.2s ease;
}

.card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  background: var(--card-hover);
}

.card h3 {
  font-size: 1.02rem;
  margin-bottom: 8px;
  color: var(--accent);
}

.card p {
  font-size: 0.92rem;
}

/* ============ Stack strip ============ */
.stack-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  padding: 20px 24px;
  border: 1px solid var(--border);
  border-radius: 16px;
  background: var(--card);
  margin-bottom: 14px;
}

.stack-chip {
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
  background: var(--bg-soft);
  border: 1px solid var(--border);
  padding: 8px 14px;
  border-radius: 999px;
}

.stack-sep {
  color: var(--accent);
  font-weight: 800;
}

.stack-note {
  font-size: 0.9rem;
}

/* ============ Footer ============ */
.footer {
  background: var(--bg-soft);
  border-top: 1px solid var(--border);
  padding: 80px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 48px;
  margin-bottom: 56px;
}

.code-block {
  background: var(--code-bg);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px 22px;
  overflow-x: auto;
}

.code-block code {
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.85rem;
  line-height: 1.8;
  color: var(--text);
  background: none;
  padding: 0;
}

.footer-status h2 {
  font-size: 1.4rem;
  margin-bottom: 10px;
}

.footer-status p {
  font-size: 0.95rem;
}

.status-line {
  margin-top: 18px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: "SFMono-Regular", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.85rem;
  color: var(--text);
}

.status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 10px var(--glow);
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 0.85rem;
}

.footer-motto {
  color: var(--text-faint);
}

/* ============ Responsive ============ */
@media (max-width: 860px) {
  .hero {
    padding: 72px 0 64px;
  }

  .hero-grid,
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .section {
    padding: 64px 0;
  }

  .nav {
    gap: 16px;
  }

  .nav a:not(:last-of-type) {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .demo-spinner,
  .status-dot {
    animation: none;
  }
}
"}

{"path": "app.js", "content": "/*
 * clutch landing page interactivity.
 *
 * Pure logic first (no DOM access) so it can be unit-tested with plain node:
 *   node app.test.js
 * DOM wiring lives only in init().
 */

/* ------------------------------------------------------------------ */
/* Pure logic                                                          */
/* ------------------------------------------------------------------ */

/** The fake event stream cycle used by the live demo. */
const EVENT_CYCLE = ["step_start", "tool_call", "tool_result", "final"];

/**
 * Return the next event in the cycle, wrapping around.
 * nextEvent("step_start") -> "tool_call"
 * nextEvent("final")      -> "step_start"
 * nextEvent(anythingElse) -> "step_start" (first event)
 *
 * @param {string|null|undefined} prev
 * @returns {string}
 */
function nextEvent(prev) {
  if (!EVENT_CYCLE.includes(prev)) {
    return EVENT_CYCLE[0];
  }
  const idx = EVENT_CYCLE.indexOf(prev);
  return EVENT_CYCLE[(idx + 1) % EVENT_CYCLE.length];
}

/**
 * Return the opposite theme.
 * toggleTheme("dark")  -> "light"
 * toggleTheme("light") -> "dark"
 * toggleTheme(anythingElse) -> "dark"
 *
 * @param {string} mode
 * @returns {string}
 */
function toggleTheme(mode) {
  return mode === "dark" ? "light" : "dark";
}

/* ------------------------------------------------------------------ */
/* DOM wiring — browser only                                           */
/* ------------------------------------------------------------------ */

const DEMO_INTERVAL_MS = 1400;
const MAX_LOG_LINES = 4;
const EVENT_STYLES = {
  step_start: { label: "step_start", cls: "ev-start" },
  tool_call: { label: "tool_call", cls: "ev-call" },
  tool_result: { label: "tool_result", cls: "ev-result" },
  final: { label: "final", cls: "ev-final" },
};

let initDone = false;

/**
 * Wire up the theme toggle and the animated event-stream demo.
 * Safe to call multiple times (idempotent). No-op outside a browser.
 */
function init() {
  if (initDone || typeof document === "undefined") {
    return;
  }
  initDone = true;

  const root = document.documentElement;

  /* --- theme toggle --- */
  const toggleBtn = document.getElementById("theme-toggle");
  if (toggleBtn) {
    toggleBtn.addEventListener("click", () => {
      const current = root.getAttribute("data-theme") || "dark";
      const next = toggleTheme(current);
      root.setAttribute("data-theme", next);
      toggleBtn.setAttribute(
        "aria-label",
        next === "dark" ? "Switch to light theme" : "Switch to dark theme"
      );
      try {
        localStorage.setItem("clutch-theme", next);
      } catch (_) {
        /* private mode / disabled storage — ignore */
      }
    });
  }

  /* --- event stream demo --- */
  const eventEl = document.getElementById("demo-event");
  const logEl = document.getElementById("demo-log");
  if (eventEl && logEl) {
    let current = nextEvent(undefined); // start at "step_start"
    const render = (ev) => {
      const style = EVENT_STYLES[ev] || { label: ev, cls: "" };
      eventEl.textContent = style.label;

      const line = document.createElement("div");
      line.className = "log-line";
      line.textContent = style.label;
      logEl.prepend(line);
      while (logEl.children.length > MAX_LOG_LINES) {
        logEl.removeChild(logEl.lastChild);
      }
    };
    render(current);
    window.setInterval(() => {
      current = nextEvent(current);
      render(current);
    }, DEMO_INTERVAL_MS);
  }
}

/* ------------------------------------------------------------------ */
/* Exports                                                             */
/* ------------------------------------------------------------------ */

/* Node / CommonJS (used by app.test.js) */
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    EVENT_CYCLE,
    nextEvent,
    toggleTheme,
  };
}

/* Browser global + auto-init */
if (typeof window !== "undefined") {
  window.clutch = { EVENT_CYCLE, nextEvent, toggleTheme, init };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
}
"}

{"path": "app.test.js", "content": "/*
 * Unit tests for the pure logic in app.js.
 * Run with: node app.test.js
 * Exits 0 with "All tests passed." on success, non-zero on any failure.
 */
const assert = require("assert");

const { EVENT_CYCLE, nextEvent, toggleTheme } = require("./app.js");

/* 1. The event cycle list is not empty */
assert.ok(
  Array.isArray(EVENT_CYCLE) && EVENT_CYCLE.length > 0,
  "EVENT_CYCLE must be a non-empty array"
);

/* 2. nextEvent cycles step_start -> tool_call -> tool_result -> final -> step_start */
const expected = [
  "step_start",
  "tool_call",
  "tool_result",
  "final",
  "step_start",
];

let ev = nextEvent(undefined);
expected.forEach((want, i) => {
  assert.strictEqual(
    ev,
    want,
    `nextEvent cycle position ${i}: expected "${want}", got "${ev}"`
  );
  ev = nextEvent(ev);
});

/* 3. toggleTheme flips between light and dark */
assert.strictEqual(
  toggleTheme("dark"),
  "light",
  'toggleTheme("dark") should return "light"'
);
assert.strictEqual(
  toggleTheme("light"),
  "dark",
  'toggleTheme("light") should return "dark"'
);

console.log("All tests passed.");
"}
